// loader (JS)
function lookup(db, entry, key, seen = new Set()) {
  if (key in entry) return entry[key];
  if (!entry.prototype) return undefined;
  if (seen.has(entry.name)) throw new Error('cycle at ' + entry.name);
  seen.add(entry.name);
  return lookup(db, db[entry.prototype], key, seen);
}

// JS-style: state on the instance, behavior on a shared prototype
